  def normalizeUA(u: ArrowType): ArrowType = {
//    println("normalizeUA: " + u + "[" + getStaticParams(u) + "]")
    val e = makeDomainFromArrow(u)
    val (ne, s) = reduceED(e).getOrElse(return u)
    val sp = getStaticParams(ne)
