"""  // Forest rule (route C shadow): the return type rule over a chain.  For f more specific
  // than g, a static parameter P of g bounded by S[P], S self-typed, that f's domain fixes
  // at a ground type M, has an applicable instance of g at every other level L of S's chain
  // through M.  One result per level whose domain meets f's: (M, L, L is below M, f's return
  // type fits g's at L, f's domain met with g's at L).  S[L] is read as L when S comprises
  // exactly its parameter, the patents' identification of the two.
  def forestLevels(x: ArrowType, y: ArrowType): List[(Type, Type, Boolean, Boolean, Type)] =
    (alphaRenameTypeSchema(x, ta.extend(toList(x.getInfo.getStaticParams), None).env),
     alphaRenameTypeSchema(y, ta.extend(toList(y.getInfo.getStaticParams), None).env)) match {
      case (fa@SArrowType(STypeInfo(_, _, sp1, _), _, r1, _, _, _),
            ga@SArrowType(STypeInfo(_, _, sp2, _), _, r2, _, _, _)) =>
        val fd = sa.makeDomainWithSelfFromArrow(fa)
        val gd = sa.makeDomainWithSelfFromArrow(ga)
        sa.subEDsolution(fd, gd) match {
          case Some((_, newargs)) if newargs.size == sp2.size =>
            val nta = ta.extend(sp1, None)
            val (fdc, gdc) = (clearStaticParams(fd), clearStaticParams(gd))
            sp2.zip(newargs).zipWithIndex.flatMap {
              case ((p, STypeArg(_, _, m)), i) if !mentionsVar(m) => forestBound(p) match {
                case Some(s) => nta.forestChain(s, m).flatMap { l =>
                  val str = new StaticTypeReplacer(sp2, newargs.updated(i, NF.makeTypeArg(l)))
                  val dl = if (ta.forestSelfTyped(s, true)) selfAsLevel(str.replaceIn(gdc), s, l)
                           else str.replaceIn(gdc)
                  if (nta.definitelyExcludes(fdc, dl)) Nil
                  else List((m, l, nta.lteq(l, m), nta.lteq(r1, str.replaceIn(r2)), nta.meet(fdc, dl)))
                }
                case None => Nil
              }
              case _ => Nil
            }
          case _ => Nil
        }
    }

  // Does f's domain met with g's at a level lie inside h's domain (so h runs there)?
  def forestCovers(meet: Type, f: ArrowType, h: ArrowType): Boolean = {
    val sp1 = toList(f.getInfo.getStaticParams)
