def forestLevels(x: ArrowType, y: ArrowType): List[(Type, Type, Boolean, Boolean, Type)] =
  (alphaRenameTypeSchema(x, ta.extend(toList(x.getInfo.getStaticParams), None).env),
   alphaRenameTypeSchema(y, ta.extend(toList(y.getInfo.getStaticParams), None).env)) match {
    case (fa@SArrowType(STypeInfo(_, _, sp1, _), _, r1, _, _, _),
          ga@SArrowType(STypeInfo(_, _, sp2, _), _, r2, _, _, _)) =>
      val fd = sa.makeDomainWithSelfFromArrow(fa)
      val gd = sa.makeDomainWithSelfFromArrow(ga)
      sa.subEDsolution(fd, gd) match {
        case Some((_, newargs)) if newargs.size == sp2.size =>
          val nta = ta.extend(sp1, None)
          val (fdc, gdc) = (clearStaticParams(fd), clearStaticParams(gd))
          sp2.zip(newargs).zipWithIndex.flatMap {
            case ((p, STypeArg(_, _, m)), i) if !mentionsVar(m) => forestBound(p) match {
              case Some(s) => nta.forestChain(s, m).flatMap { l =>
                val str = new StaticTypeReplacer(sp2, newargs.updated(i, NF.makeTypeArg(l)))
                val gl = str.replaceIn(gdc)
                val dl = if (ta.forestSelfTyped(s, true)) selfAsLevel(gl, s) else gl
                if (nta.definitelyExcludes(fdc, dl)) Nil
                else List((m, l, !nta.lteq(selfAsLevel(fdc, s), selfAsLevel(gl, s)),
                           nta.lteq(r1, str.replaceIn(r2)), nta.meet(fdc, dl)))
              }
              case None => Nil
            }
            case _ => Nil
          }
        case _ => Nil
      }
  }
def forestLevels(x: ArrowType, y: ArrowType): List[(Type, Type, Boolean, Boolean)] =
  (alphaRenameTypeSchema(x, ta.extend(toList(x.getInfo.getStaticParams), None).env),
   alphaRenameTypeSchema(y, ta.extend(toList(y.getInfo.getStaticParams), None).env)) match {
    case (fa@SArrowType(STypeInfo(_, _, sp1, _), _, r1, _, _, _),
          ga@SArrowType(STypeInfo(_, _, sp2, _), _, r2, _, _, _)) =>
      val fd = sa.makeDomainWithSelfFromArrow(fa)
      val gd = sa.makeDomainWithSelfFromArrow(ga)
      sa.subEDsolution(fd, gd) match {
        case Some((_, newargs)) if newargs.size == sp2.size =>
          val nta = ta.extend(sp1, None)
          val (fdc, gdc) = (clearStaticParams(fd), clearStaticParams(gd))
          sp2.zip(newargs).zipWithIndex.flatMap {
            case ((p, STypeArg(_, _, m)), i) if !mentionsVar(m) => forestBound(p) match {
              case Some(s) => nta.forestChain(s, m).flatMap { l =>
                val str = new StaticTypeReplacer(sp2, newargs.updated(i, NF.makeTypeArg(l)))
                val gl = str.replaceIn(gdc)
                if (nta.definitelyExcludes(fdc, gl)) Nil
                else List((m, l, !nta.lteq(selfAsLevel(fdc, s), selfAsLevel(gl, s)),
                           nta.lteq(r1, str.replaceIn(r2))))
              }
              case None => Nil
            }
            case _ => Nil
          }
        case _ => Nil
      }
  }

  case (s@STupleType(_, e1, None, _), t@STupleType(_, e2, Some(v2), _)) => pExc(t, s)
  case (STupleType(_, e1, None, _), STupleType(_, e2, None, _)) if (e1.size == e2.size) =>
    pOr((e1, e2).zipped.map((a, b) => pExc(a, b)))
  case (STupleType(_, e1, None, _), STupleType(_, e2, None, _)) =>
    pTrue()
  case (s: TupleType, t) => pExc(disjunctFromTuple(s, 1), t)
  case (s, t: TupleType) => pExc(t, s)
  case (s: ArrowType, t: ArrowType) => pFalse()
  case (s: ArrowType, t) => pTrue()
  case (s, t: ArrowType) => pExc(t, s)
}

protected def removeSelf(x: Type) = {
  object remover extends Walker {
    override def walk(y: Any): Any = y match {
      case t:TraitSelfType =>
        if (t.getComprised.isEmpty)
          t.getNamed
        else
          NF.makeIntersectionType(t.getNamed, NF.makeMaybeUnionType(t.getComprised))
      case t:ObjectExprType => NF.makeMaybeIntersectionType(t.getExtended)
      case _ => super.walk(y)
    }
  }
  remover(x).asInstanceOf[Type]
}
/*
 * For is-subtype queries, it makes no sense to stir in the comprised types;
 * if this is a subtype, then so are they
 * (unless they are declared to exclude -- but does that matter?) 
 */
protected def removeSelfAsSubtype(x: Type) = {
  object remover extends Walker {
    override def walk(y: Any): Any = y match {
      case t:TraitSelfType => t.getNamed
      case t:ObjectExprType => NF.makeMaybeIntersectionType(t.getExtended)
      case _ => super.walk(y)
    }
  }
  remover(x).asInstanceOf[Type]
}


